# Terraform Dev/Prod Refactoring to for_each Module

## Strategy

The safest path to zero-diff state migration is:
1. Create a reusable module parametrized by environment
2. Use `moved` blocks to alias old resource addresses to new ones
3. Apply in a single run—Terraform updates state references without touching infrastructure
4. Remove `moved` blocks after verification

---

## Before: Duplicated Blocks

```hcl
# main.tf (simplified, but illustrative)

resource "aws_eks_cluster" "dev" {
  name            = "app-dev"
  version         = "1.28"
  role_arn        = aws_iam_role.eks_dev.arn
  vpc_config {
    subnet_ids = var.vpc_subnet_ids_dev
  }
  tags = { Environment = "dev" }
}

resource "aws_eks_node_group" "dev" {
  cluster_name    = aws_eks_cluster.dev.name
  node_group_name = "app-dev-nodes"
  node_role_arn   = aws_iam_role.node_dev.arn
  subnet_ids      = var.vpc_subnet_ids_dev
  desired_size    = 2
  min_size        = 2
  max_size        = 4
  instance_types  = ["t3.medium"]
}

resource "aws_s3_bucket" "dev" {
  bucket = "app-assets-dev-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_versioning" "dev" {
  bucket = aws_s3_bucket.dev.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "dev" {
  bucket = aws_s3_bucket.dev.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
}

resource "aws_db_instance" "dev" {
  identifier          = "app-db-dev"
  engine              = "postgres"
  engine_version      = "15.4"
  instance_class      = "db.t3.micro"
  allocated_storage   = 20
  storage_type        = "gp3"
  username            = "postgres"
  password            = random_password.db_dev.result
  multi_az            = false
  backup_retention_period = 7
  deletion_protection = true
  publicly_accessible = false
}

# ... (identical structure for prod, just with prod suffix and different values)

resource "aws_eks_cluster" "prod" {
  name            = "app-prod"
  version         = "1.28"
  role_arn        = aws_iam_role.eks_prod.arn
  vpc_config {
    subnet_ids = var.vpc_subnet_ids_prod
  }
  tags = { Environment = "prod" }
}

resource "aws_eks_node_group" "prod" {
  cluster_name    = aws_eks_cluster.prod.name
  node_group_name = "app-prod-nodes"
  node_role_arn   = aws_iam_role.node_prod.arn
  subnet_ids      = var.vpc_subnet_ids_prod
  desired_size    = 4
  min_size        = 4
  max_size        = 8
  instance_types  = ["t3.large"]
}

resource "aws_s3_bucket" "prod" {
  bucket = "app-assets-prod-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_versioning" "prod" {
  bucket = aws_s3_bucket.prod.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "prod" {
  bucket = aws_s3_bucket.prod.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
}

resource "aws_s3_bucket_replication_configuration" "prod" {
  bucket = aws_s3_bucket.prod.id
  # ... cross-region replication to us-west-2
}

resource "aws_db_instance" "prod" {
  identifier          = "app-db-prod"
  engine              = "postgres"
  engine_version      = "15.4"
  instance_class      = "db.t3.medium"
  allocated_storage   = 100
  storage_type        = "gp3"
  username            = "postgres"
  password            = random_password.db_prod.result
  multi_az            = true
  backup_retention_period = 30
  deletion_protection = true
  storage_encrypted   = true
  publicly_accessible = false
}
```

---

## After: Module-Based with for_each

### 1. Module Directory Structure

```
├── main.tf                    # Root module: defines for_each instantiation
├── modules/
│   └── environment/
│       ├── main.tf            # EKS, S3, RDS resources
│       ├── variables.tf        # env-specific inputs
│       ├── outputs.tf          # resource references for root
│       └── locals.tf           # computed values (e.g., naming)
├── prod.tfvars                # prod variable overrides
└── dev.tfvars                 # dev variable overrides
```

### 2. Root Module: main.tf

```hcl
# main.tf - root

terraform {
  required_version = ">= 1.3"
}

data "aws_caller_identity" "current" {}

module "environment" {
  for_each = toset(["dev", "prod"])

  source = "./modules/environment"

  environment              = each.key
  eks_desired_size         = each.key == "dev" ? 2 : 4
  eks_min_size             = each.key == "dev" ? 2 : 4
  eks_max_size             = each.key == "dev" ? 4 : 8
  eks_instance_type        = each.key == "dev" ? ["t3.medium"] : ["t3.large"]
  rds_instance_class       = each.key == "dev" ? "db.t3.micro" : "db.t3.medium"
  rds_allocated_storage    = each.key == "dev" ? 20 : 100
  rds_multi_az             = each.key == "dev" ? false : true
  rds_backup_retention     = each.key == "dev" ? 7 : 30
  rds_storage_encrypted    = each.key == "dev" ? false : true
  s3_enable_replication    = each.key == "dev" ? false : true
  s3_replication_region    = "us-west-2"
  vpc_subnet_ids           = var.vpc_subnet_ids[each.key]
  db_password              = var.db_password[each.key]
  aws_account_id           = data.aws_caller_identity.current.account_id
}

# ============================================================================
# MIGRATION: moved blocks (keep until state migration confirmed, then remove)
# ============================================================================

moved {
  from = aws_eks_cluster.dev
  to   = module.environment["dev"].aws_eks_cluster.this
}

moved {
  from = aws_eks_node_group.dev
  to   = module.environment["dev"].aws_eks_node_group.this
}

moved {
  from = aws_s3_bucket.dev
  to   = module.environment["dev"].aws_s3_bucket.this
}

moved {
  from = aws_s3_bucket_versioning.dev
  to   = module.environment["dev"].aws_s3_bucket_versioning.this
}

moved {
  from = aws_s3_bucket_server_side_encryption_configuration.dev
  to   = module.environment["dev"].aws_s3_bucket_server_side_encryption_configuration.this
}

moved {
  from = aws_db_instance.dev
  to   = module.environment["dev"].aws_db_instance.this
}

moved {
  from = aws_eks_cluster.prod
  to   = module.environment["prod"].aws_eks_cluster.this
}

moved {
  from = aws_eks_node_group.prod
  to   = module.environment["prod"].aws_eks_node_group.this
}

moved {
  from = aws_s3_bucket.prod
  to   = module.environment["prod"].aws_s3_bucket.this
}

moved {
  from = aws_s3_bucket_versioning.prod
  to   = module.environment["prod"].aws_s3_bucket_versioning.this
}

moved {
  from = aws_s3_bucket_server_side_encryption_configuration.prod
  to   = module.environment["prod"].aws_s3_bucket_server_side_encryption_configuration.this
}

moved {
  from = aws_s3_bucket_replication_configuration.prod
  to   = module.environment["prod"].aws_s3_bucket_replication_configuration.this
}

moved {
  from = aws_db_instance.prod
  to   = module.environment["prod"].aws_db_instance.this
}
```

### 3. Module: modules/environment/variables.tf

```hcl
variable "environment" {
  type        = string
  description = "Environment name: dev or prod"
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod"
  }
}

variable "eks_desired_size" {
  type    = number
  default = 2
}

variable "eks_min_size" {
  type    = number
  default = 2
}

variable "eks_max_size" {
  type    = number
  default = 4
}

variable "eks_instance_type" {
  type    = list(string)
  default = ["t3.medium"]
}

variable "rds_instance_class" {
  type    = string
  default = "db.t3.micro"
}

variable "rds_allocated_storage" {
  type    = number
  default = 20
}

variable "rds_multi_az" {
  type    = bool
  default = false
}

variable "rds_backup_retention" {
  type    = number
  default = 7
}

variable "rds_storage_encrypted" {
  type    = bool
  default = false
}

variable "s3_enable_replication" {
  type    = bool
  default = false
}

variable "s3_replication_region" {
  type    = string
  default = "us-west-2"
}

variable "vpc_subnet_ids" {
  type    = list(string)
  description = "VPC subnet IDs for this environment"
}

variable "db_password" {
  type      = string
  sensitive = true
  description = "RDS master password (should come from AWS Secrets Manager in production)"
}

variable "aws_account_id" {
  type    = string
  description = "AWS account ID for resource naming"
}
```

### 4. Module: modules/environment/locals.tf

```hcl
locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Module      = "environment"
  }

  s3_bucket_name = "app-assets-${var.environment}-${var.aws_account_id}"
  db_identifier  = "app-db-${var.environment}"
  eks_name       = "app-${var.environment}"
}
```

### 5. Module: modules/environment/main.tf

```hcl
# ============================================================================
# IAM Roles (simplified; expand as needed for OIDC, etc.)
# ============================================================================

resource "aws_iam_role" "eks" {
  name = "eks-cluster-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks" {
  role       = aws_iam_role.eks.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "node" {
  name = "eks-node-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_ecr" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# ============================================================================
# EKS Cluster
# ============================================================================

resource "aws_eks_cluster" "this" {
  name     = local.eks_name
  version  = "1.28"
  role_arn = aws_iam_role.eks.arn

  vpc_config {
    subnet_ids = var.vpc_subnet_ids
  }

  tags = local.common_tags

  depends_on = [aws_iam_role_policy_attachment.eks]
}

# ============================================================================
# EKS Node Group
# ============================================================================

resource "aws_eks_node_group" "this" {
  cluster_name    = aws_eks_cluster.this.name
  node_group_name = "${local.eks_name}-nodes"
  node_role_arn   = aws_iam_role.node.arn
  subnet_ids      = var.vpc_subnet_ids

  desired_size   = var.eks_desired_size
  min_size       = var.eks_min_size
  max_size       = var.eks_max_size
  instance_types = var.eks_instance_type

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.node_cni,
    aws_iam_role_policy_attachment.node_worker,
  ]
}

# ============================================================================
# S3 Bucket (Application Assets)
# ============================================================================

resource "aws_s3_bucket" "this" {
  bucket = local.s3_bucket_name

  tags = local.common_tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.s3_enable_replication ? 1 : 0

  bucket = aws_s3_bucket.this.id

  role = aws_iam_role.s3_replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    destination {
      bucket       = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket" "replica" {
  count    = var.s3_enable_replication ? 1 : 0
  bucket   = "${local.s3_bucket_name}-replica-${var.s3_replication_region}"
  provider = aws.replica

  tags = merge(local.common_tags, { Role = "replica" })
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.s3_enable_replication ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id
  provider = aws.replica

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "s3_replication" {
  count = var.s3_enable_replication ? 1 : 0
  name  = "s3-replication-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  count  = var.s3_enable_replication ? 1 : 0
  name   = "s3-replication-policy-${var.environment}"
  role   = aws_iam_role.s3_replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
        ]
        Resource = aws_s3_bucket.this.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
        ]
        Resource = "${aws_s3_bucket.this.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
        ]
        Resource = "${aws_s3_bucket.replica[0].arn}/*"
      }
    ]
  })
}

# ============================================================================
# RDS PostgreSQL Instance
# ============================================================================

resource "aws_db_instance" "this" {
  identifier          = local.db_identifier
  engine              = "postgres"
  engine_version      = "15.4"
  instance_class      = var.rds_instance_class
  allocated_storage   = var.rds_allocated_storage
  storage_type        = "gp3"
  username            = "postgres"
  password            = var.db_password
  multi_az            = var.rds_multi_az
  storage_encrypted   = var.rds_storage_encrypted
  backup_retention_period = var.rds_backup_retention
  deletion_protection = true
  publicly_accessible = false
  skip_final_snapshot = var.environment == "dev" ? true : false

  tags = local.common_tags
}
```

### 6. Module: modules/environment/outputs.tf

```hcl
output "eks_cluster_name" {
  value       = aws_eks_cluster.this.name
  description = "EKS cluster name"
}

output "eks_cluster_arn" {
  value       = aws_eks_cluster.this.arn
  description = "EKS cluster ARN"
}

output "s3_bucket_name" {
  value       = aws_s3_bucket.this.id
  description = "S3 bucket name for application assets"
}

output "rds_endpoint" {
  value       = aws_db_instance.this.endpoint
  description = "RDS database endpoint"
}

output "rds_address" {
  value       = aws_db_instance.this.address
  description = "RDS database address (hostname only)"
}
```

